create table if not exists public.portal_regras_categoria (ordem int primary key, categoria text not null, chaves text[] not null);
alter table public.portal_regras_categoria enable row level security;
drop policy if exists regras_leitura on public.portal_regras_categoria;
create policy regras_leitura on public.portal_regras_categoria for select to anon, authenticated using (true);
revoke insert, update, delete on public.portal_regras_categoria from anon, authenticated;
delete from public.portal_regras_categoria;
