create or replace function public.portal_categoria_pelo_nome(p_nome text) returns text language plpgsql stable set search_path = public as $f$
declare t text; prim text; r record; k text;
begin
  t := ' ' || btrim(regexp_replace(lower(translate(coalesce(p_nome,''),'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇçÑñ','AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCcNn')),'[^a-z0-9]+',' ','g')) || ' ';
  prim := split_part(btrim(t),' ',1);
  for r in select * from portal_regras_categoria order by ordem loop
    foreach k in array r.chaves loop if position(' ' in k) > 0 and left(t, length(k)+2) = ' '||k||' ' then return r.categoria; end if; end loop; end loop;
  for r in select * from portal_regras_categoria order by ordem loop
    foreach k in array r.chaves loop if position(' ' in k) = 0 and prim = k then return r.categoria; end if; end loop; end loop;
  for r in select * from portal_regras_categoria order by ordem loop
    foreach k in array r.chaves loop if position(' ' in k) = 0 and length(k) >= 4 and left(prim, length(k)) = k then return r.categoria; end if; end loop; end loop;
  for r in select * from portal_regras_categoria order by ordem loop
    foreach k in array r.chaves loop if length(k) >= 3 and position(' '||k in t) > 0 then return r.categoria; end if; end loop; end loop;
  return 'Outros';
end $f$;
revoke execute on function public.portal_categoria_pelo_nome(text) from anon, authenticated, public;
